  @Override public void onMapReady(GoogleMap g){map=g;map.setMapType(GoogleMap.MAP_TYPE_NORMAL);try{map.setMapStyle(MapStyleOptions.loadRawResourceStyle(this,R.raw.google_map_style));}catch(Exception ignored){}map.getUiSettings().setMapToolbarEnabled(false);map.getUiSettings().setRotateGesturesEnabled(true);map.getUiSettings().setCompassEnabled(true);map.getUiSettings().setMyLocationButtonEnabled(false);map.setOnMapLoadedCallback(()->{mapLoaded=true;if(mapMessage!=null)mapMessage.setVisibility(View.GONE);});try{if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED){map.setMyLocationEnabled(true);location.getLastLocation().addOnSuccessListener(p->{if(p!=null){foregroundLocation=p;if(active==null)map.animateCamera(CameraUpdateFactory.newLatLngZoom(new LatLng(p.getLatitude(),p.getLongitude()),15));else refreshLiveRoute(true);}});startForegroundMapUpdates();}}catch(SecurityException ignored){}map.moveCamera(CameraUpdateFactory.newLatLngZoom(new LatLng(-20.999,-48.221),14));updateMap();}
  private void sync(){io.execute(()->{try{JSONObject next=api.get("/api/delivery/state"),pending=null;try{pending=api.get("/api/delivery/pending");}catch(Exception ignored){}JSONObject finalPending=pending;runOnUiThread(()->{pendingState=finalPending;applyState(next);});}catch(Exception e){runOnUiThread(()->toast("Sem conexão. Tentando novamente."));}});}
  private void applyState(JSONObject next){if(!hasOperationalAccess(next)){showAccessGate(next);return;}state=next;profile=next.optJSONObject("profile");orders=next.optJSONArray("orders");offers=next.optJSONArray("offers");active=findActive();boolean available=profile!=null&&profile.optBoolean("is_available");availability.setText(active!=null?"Entrega em andamento":available?"Ficar indisponível":"Ficar disponível");availability.setEnabled(active==null&&!busy);status.setText(active!=null?label(active):available?"●  Livre · buscando novas entregas":"○  Indisponível");status.setTextColor(active!=null?PURPLE:available?SUCCESS:MUTED);balance.setText(hideEarnings?"R$ ••••  ›":money(totalToday())+"  ›");int pending=pendingCount();if(pendingBadge!=null){pendingBadge.setText(String.valueOf(pending));pendingBadge.setVisibility(pending>0?View.VISIBLE:View.GONE);}if(idleDock!=null)idleDock.setVisibility(active==null?View.VISIBLE:View.GONE);updateMap();refreshLiveRoute(false);startService(true,active!=null,available);if(active!=null){dismissOffer();showActiveCard();updateRouteSummary();}else{routePoints.clear();routeKey="";routeSummary=null;clearActiveCard();JSONObject visible=firstVisibleOffer();if(visible!=null)showOffer(visible);else dismissOffer();}}
  private int pendingCount(){if(pendingState==null)return visibleOfferCount();JSONArray available=pendingState.optJSONArray("available"),decisions=pendingState.optJSONArray("decisions");return (available==null?0:available.length())+(decisions==null?0:decisions.length());}
  private JSONObject firstVisibleOffer(){if(offers==null)return null;long now=System.currentTimeMillis();for(int i=0;i<offers.length();i++){JSONObject offer=offers.optJSONObject(i);if(offer!=null&&!offerDecisions.isSuppressed(offer.optString("id"),now))return offer;}return null;}
  private int visibleOfferCount(){if(offers==null)return 0;int count=0;long now=System.currentTimeMillis();for(int i=0;i<offers.length();i++){JSONObject offer=offers.optJSONObject(i);if(offer!=null&&!offerDecisions.isSuppressed(offer.optString("id"),now))count++;}return count;}
  private JSONObject findActive(){if(orders==null)return null;JSONObject chosen=null;int sequence=Integer.MAX_VALUE;for(int i=0;i<orders.length();i++){JSONObject o=orders.optJSONObject(i);String status=o.optString("status");if(!"assigned".equals(status)&&!"collected".equals(status))continue;int current=o.isNull("route_sequence")?Integer.MAX_VALUE-1:o.optInt("route_sequence");if(chosen==null||current<sequence){chosen=o;sequence=current;}}return chosen;}
  private void updateMap(){if(map==null)return;String key=active==null?"idle":active.optString("id")+":"+active.optString("status")+":"+active.optString("return_started_at")+":"+routePoints.size()+":"+(lastRouteOrigin==null?"none":String.format(Locale.US,"%.4f,%.4f",lastRouteOrigin.getLatitude(),lastRouteOrigin.getLongitude()));if(key.equals(mapRenderKey))return;mapRenderKey=key;map.clear();LatLngBounds.Builder bounds=new LatLngBounds.Builder();int count=0;if(active!=null){double plat=active.optDouble("pickup_lat",Double.NaN),plng=active.optDouble("pickup_lng",Double.NaN),dlat=active.optDouble("lat",Double.NaN),dlng=active.optDouble("lng",Double.NaN);if(!Double.isNaN(plat)&&!Double.isNaN(plng)){LatLng p=new LatLng(plat,plng);map.addMarker(new MarkerOptions().position(p).title("Coleta").icon(BitmapDescriptorFactory.defaultMarker(BitmapDescriptorFactory.HUE_ORANGE)));bounds.include(p);count++;}if(!Double.isNaN(dlat)&&!Double.isNaN(dlng)){LatLng d=new LatLng(dlat,dlng);map.addMarker(new MarkerOptions().position(d).title("Destino").icon(BitmapDescriptorFactory.defaultMarker(BitmapDescriptorFactory.HUE_VIOLET)));bounds.include(d);count++;}if(!routePoints.isEmpty()){map.addPolyline(new PolylineOptions().addAll(routePoints).color(Color.WHITE).width(dp(10)).zIndex(2));map.addPolyline(new PolylineOptions().addAll(routePoints).color(PURPLE).width(dp(6)).geodesic(true).zIndex(3));for(LatLng point:routePoints)bounds.include(point);count+=routePoints.size();}if(foregroundLocation!=null){LatLng here=new LatLng(foregroundLocation.getLatitude(),foregroundLocation.getLongitude());bounds.include(here);count++;}if(fitRouteCamera&&count>1)try{map.animateCamera(CameraUpdateFactory.newLatLngBounds(bounds.build(),dp(90)));fitRouteCamera=false;}catch(Exception ignored){}}}
  private void startForegroundMapUpdates(){if(foregroundLocationCallback!=null||checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)return;foregroundLocationCallback=new LocationCallback(){@Override public void onLocationResult(LocationResult result){android.location.Location current=result.getLastLocation();if(current==null)return;foregroundLocation=current;refreshLiveRoute(false);}};LocationRequest request=new LocationRequest.Builder(Priority.PRIORITY_HIGH_ACCURACY,2500).setMinUpdateIntervalMillis(1200).setMinUpdateDistanceMeters(2).build();location.requestLocationUpdates(request,foregroundLocationCallback,Looper.getMainLooper());}
  private void stopForegroundMapUpdates(){if(foregroundLocationCallback==null)return;location.removeLocationUpdates(foregroundLocationCallback);foregroundLocationCallback=null;}
  private void refreshLiveRoute(boolean force){if(active==null||foregroundLocation==null||routeLoading)return;String key=active.optString("id")+":"+active.optString("status")+":"+isReturning(active);float moved=lastRouteOrigin==null?Float.MAX_VALUE:foregroundLocation.distanceTo(lastRouteOrigin);boolean newRoute=!key.equals(routeKey);if(newRoute){routeKey=key;routePoints.clear();routeDistance=routeDuration=0;force=true;}long now=System.currentTimeMillis();if(!force&&now-lastRouteAt<18000&&moved<35)return;routeLoading=true;lastRouteAt=now;android.location.Location origin=new android.location.Location(foregroundLocation);String path="/api/delivery/route?id="+Uri.encode(active.optString("id"))+"&lat="+origin.getLatitude()+"&lng="+origin.getLongitude();io.execute(()->{try{JSONObject data=api.get(path);List<LatLng> decoded=new ArrayList<>();for(double[] point:PolylineDecoder.decode(data.optString("polyline")))decoded.add(new LatLng(point[0],point[1]));runOnUiThread(()->{routePoints.clear();routePoints.addAll(decoded);routeDistance=data.optInt("distance_m");routeDuration=data.optInt("duration_s");lastRouteOrigin=origin;fitRouteCamera=newRoute;routeLoading=false;speakGuidance(data.optJSONArray("instructions"));updateRouteSummary();updateMap();});}catch(Exception error){runOnUiThread(()->{routeLoading=false;if(routeSummary!=null)routeSummary.setText("Rota ao vivo indisponível. Tentando novamente…");});}});}
  private void updateRouteSummary(){if(routeSummary==null)return;if(routeDistance<=0){routeSummary.setText("Calculando rota ao vivo…");return;}routeSummary.setText(String.format(Locale.forLanguageTag("pt-BR"),"Rota ao vivo · %.1f km · %d min",routeDistance/1000.0,Math.max(1,(int)Math.ceil(routeDuration/60.0))));}
