  private void advance(){if(active==null||busy)return;String action;if(isReturning(active))action="return_finalize";else if("collected".equals(active.optString("status")))action="complete";else if(!hasPickupArrival(active))action="arrive_pickup";else action="collect";busy=true;primary.setActionEnabled(false);act(action,json("id",active.optString("id")),action.equals("return_finalize")?"Retorno concluído. Valor registrado na carteira.":action.equals("complete")?"Entrega concluída. Valor registrado na carteira.":action.equals("arrive_pickup")?"Chegada ao estabelecimento confirmada.":"Coleta confirmada.");}
  private void act(String action,JSONObject data,String ok){JSONObject snapshot=findOrder(state,data.optString("id"));io.execute(()->{try{JSONObject result=api.action(action,data);JSONObject next=api.get("/api/delivery/state");runOnUiThread(()->{busy=false;clearActiveCard();boolean startedReturn="complete".equals(action)&&result.optBoolean("return_required");boolean completed=("complete".equals(action)&&!startedReturn)||"return_finalize".equals(action);applyState(next);JSONObject completedOrder=findOrder(next,data.optString("id"));if(completedOrder==null)completedOrder=snapshot;if(completed)showEarningsReceipt(completedOrder);else toast(startedReturn?"Destino concluído. Agora retorne ao estabelecimento.":ok);});}catch(Exception e){runOnUiThread(()->{busy=false;if(primary!=null)primary.setActionEnabled(true);availability.setEnabled(true);toast(e.getMessage());});}});}
