  private void renderWallet(LinearLayout body,JSONObject summary){
    body.removeAllViews();JSONObject finance=summary==null?null:summary.optJSONObject("state"),wallet=finance==null?null:finance.optJSONObject("wallet"),balances=wallet==null?null:wallet.optJSONObject("balances");
    int current=balances==null?total():balances.optInt("available",total()),blocked=balances==null?0:balances.optInt("reserved",0),processing=balances==null?0:balances.optInt("processing",0);
    LinearLayout hero=new LinearLayout(this);hero.setOrientation(LinearLayout.VERTICAL);hero.setPadding(dp(22),dp(22),dp(22),dp(22));hero.setBackground(verticalGradient(PURPLE_DARK,Color.rgb(100,27,176),24));TextView cap=text("DISPONÍVEL PARA SAQUE",12,true);cap.setTextColor(Color.rgb(221,203,244));hero.addView(cap);TextView amount=text(money(current),34,true);amount.setTextColor(Color.WHITE);hero.addView(amount,lp(-1,-2,8,3));TextView available=text("Carteira atualizada pelo razão financeiro VUPPI",14,false);available.setTextColor(Color.rgb(232,220,245));hero.addView(available);body.addView(hero,new LinearLayout.LayoutParams(-1,-2));
    LinearLayout moneyStats=new LinearLayout(this);moneyStats.addView(metric("Bloqueado",money(blocked)),new LinearLayout.LayoutParams(0,dp(96),1));moneyStats.addView(metric("Em processamento",money(processing)),new LinearLayout.LayoutParams(0,dp(96),1));body.addView(moneyStats,lp(-1,dp(96),0,12));Button withdraw=button("Solicitar saque via Pix");withdraw.setEnabled(current>0);withdraw.setAlpha(current>0?1f:.55f);body.addView(withdraw,lp(-1,dp(56),0,18));withdraw.setOnClickListener(v->withdrawDialog(current,body));
    int today=0,yesterday=0,week=0,month=0;for(int i=0;orders!=null&&i<orders.length();i++){JSONObject o=orders.optJSONObject(i);if(!"delivered".equals(o.optString("status")))continue;int days=daysAgo(o);if(days==0)today++;if(days==1)yesterday++;if(days>=0&&days<7)week++;if(days>=0&&days<31)month++;}
    TextView performance=text("ENTREGAS CONCLUÍDAS",11,true);performance.setLetterSpacing(.08f);performance.setTextColor(MUTED);body.addView(performance,lp(-1,-2,2,8));LinearLayout periods=new LinearLayout(this);periods.addView(metric("Hoje",String.valueOf(today)),new LinearLayout.LayoutParams(0,dp(96),1));periods.addView(metric("Ontem",String.valueOf(yesterday)),new LinearLayout.LayoutParams(0,dp(96),1));periods.addView(metric("7 dias",String.valueOf(week)),new LinearLayout.LayoutParams(0,dp(96),1));periods.addView(metric("30 dias",String.valueOf(month)),new LinearLayout.LayoutParams(0,dp(96),1));body.addView(periods,lp(-1,dp(96),0,12));
    JSONArray entries=summary==null?null:summary.optJSONArray("entries");TextView movementTitle=text("ÚLTIMAS MOVIMENTAÇÕES",11,true);movementTitle.setLetterSpacing(.08f);movementTitle.setTextColor(MUTED);body.addView(movementTitle,lp(-1,-2,4,8));if(entries!=null&&entries.length()>0){for(int i=0;i<entries.length();i++){JSONObject entry=entries.optJSONObject(i);if(entry==null)continue;LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(15),dp(13),dp(15),dp(13));row.setBackground(round(Color.WHITE,1,Color.rgb(232,225,240),15));LinearLayout copy=new LinearLayout(this);copy.setOrientation(LinearLayout.VERTICAL);copy.addView(text(entry.optString("description","Crédito de entrega"),14,true));TextView date=text(entry.optString("created_at","").replace('T',' ').replace("Z",""),11,false);date.setTextColor(MUTED);copy.addView(date);row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));boolean credit="credit".equals(entry.optString("direction"));TextView value=text((credit?"+ ":"- ")+money(entry.optInt("amount_cents")),15,true);value.setTextColor(credit?SUCCESS:Color.rgb(190,53,78));row.addView(value);body.addView(row,lp(-1,-2,0,8));}}else{TextView empty=text("Nenhuma movimentação financeira registrada ainda.",14,false);empty.setTextColor(MUTED);empty.setGravity(Gravity.CENTER);empty.setPadding(dp(16),dp(22),dp(16),dp(22));empty.setBackground(round(Color.WHITE,1,Color.rgb(232,225,240),15));body.addView(empty);}body.addView(promoBanner(),lp(-1,dp(148),8,16));TextView note=text("Cada OS concluída gera um único lançamento auditável. Tentativas repetidas não duplicam o crédito.",13,false);note.setPadding(dp(14),dp(12),dp(14),dp(12));note.setBackground(round(Color.rgb(242,236,249),0,0,14));body.addView(note);
  }
  private void withdrawDialog(int availableCents,LinearLayout walletBody){
    Dialog d=screenDialog();LinearLayout page=screenPage(d,"Solicitar saque","O valor fica reservado e aparece em processamento até a aprovação da central.");ScrollView scroll=new ScrollView(this);LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(18),dp(8),dp(18),dp(26));scroll.addView(form);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
    LinearLayout balanceCard=new LinearLayout(this);balanceCard.setOrientation(LinearLayout.VERTICAL);balanceCard.setPadding(dp(18),dp(16),dp(18),dp(16));balanceCard.setBackground(round(Color.rgb(240,233,250),0,0,17));TextView label=text("SALDO DISPONÍVEL",11,true);label.setTextColor(PURPLE);balanceCard.addView(label);balanceCard.addView(text(money(availableCents),27,true),lp(-1,-2,5,0));form.addView(balanceCard,lp(-1,-2,0,14));
    form.addView(text("Valor do saque",13,true));EditText amount=field("Ex.: 50,00",false);amount.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);form.addView(amount,lp(-1,dp(56),7,13));form.addView(text("Chave Pix",13,true));EditText pix=field("CPF, telefone, e-mail ou chave aleatória",false);form.addView(pix,lp(-1,dp(56),7,8));TextView warning=text("Confira a chave antes de enviar. A central nunca solicita senha ou código de acesso.",12,false);warning.setTextColor(MUTED);form.addView(warning,lp(-1,-2,0,16));Button submit=button("Confirmar solicitação de saque");form.addView(submit);
    submit.setOnClickListener(v->{String raw=amount.getText().toString().trim().replace(".","").replace(',','.');int cents;try{cents=(int)Math.round(Double.parseDouble(raw)*100);}catch(Exception error){toast("Informe um valor válido.");return;}String pixKey=pix.getText().toString().trim();if(cents<=0||cents>availableCents){toast("O valor precisa estar dentro do saldo disponível.");return;}if(pixKey.length()<5){toast("Informe uma chave Pix válida.");return;}submit.setEnabled(false);submit.setText("Reservando saque…");JSONObject data=new JSONObject();try{data.put("amount_cents",cents);data.put("pix_key_masked",pixKey);data.put("idempotency_key",java.util.UUID.randomUUID().toString());}catch(Exception ignored){}io.execute(()->{try{JSONObject payload=new JSONObject();payload.put("action","withdraw_request");payload.put("data",data);api.post("/api/finance/action",payload);JSONObject fresh=api.get("/api/finance/summary?limit=30");runOnUiThread(()->{d.dismiss();renderWallet(walletBody,fresh);toast("Saque solicitado. Acompanhe o processamento na carteira.");});}catch(Exception error){runOnUiThread(()->{submit.setEnabled(true);submit.setText("Confirmar solicitação de saque");toast(error.getMessage());});}});});d.show();fitScreen(d);
  }
