    io.execute(()->{try{JSONObject result=api.get("/api/delivery/messages");JSONArray rows=result.optJSONArray("messages");runOnUiThread(()->{page.removeView(loading);ScrollView scroll=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(18),dp(4),dp(18),dp(26));scroll.addView(list);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));if(rows==null||rows.length()==0){TextView empty=text("Nenhuma mensagem nova.\nOs comunicados da central aparecerão aqui.",16,true);empty.setGravity(Gravity.CENTER);empty.setTextColor(Color.GRAY);list.addView(empty,new LinearLayout.LayoutParams(-1,dp(260)));return;}for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null)continue;LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(17),dp(15),dp(17),dp(15));int priorityColor="urgent".equals(row.optString("priority"))?Color.rgb(202,45,80):PURPLE;card.setBackground(round(Color.WHITE,1,Color.rgb(224,213,239),18));TextView tag=text("urgent".equals(row.optString("priority"))?"URGENTE":"important".equals(row.optString("priority"))?"IMPORTANTE":"COMUNICADO",10,true);tag.setTextColor(priorityColor);tag.setLetterSpacing(.08f);card.addView(tag);card.addView(text(row.optString("title","Mensagem da central"),19,true),lp(-1,-2,7,5));TextView copy=text(row.optString("body",""),14,false);copy.setTextColor(Color.DKGRAY);card.addView(copy);if(row.isNull("read_at")){TextView unread=text("NOVA · toque para marcar como lida",11,true);unread.setTextColor(priorityColor);card.addView(unread,lp(-1,-2,10,0));card.setOnClickListener(v->{v.setAlpha(.65f);io.execute(()->{try{JSONObject payload=new JSONObject();payload.put("id",row.optString("id"));api.action("message_read",payload);}catch(Exception ignored){}});});}LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,0,0,dp(11));list.addView(card,cp);}});}catch(Exception error){runOnUiThread(()->{loading.setText("Não foi possível carregar as mensagens agora.");loading.setTextColor(Color.rgb(180,45,70));});}});
