    Dialog d=screenDialog();LinearLayout page=screenPage(d,"Quero ser entregador","Preencha seus dados. A central analisará o cadastro antes da liberação.");ScrollView scroll=new ScrollView(this);LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(18),dp(4),dp(18),dp(28));scroll.addView(form);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
    EditText name=field("Nome completo",false),email=field("E-mail",false),password=field("Senha com 8 caracteres",true),phone=field("Telefone com DDD",false),address=field("Endereço completo com número",false);for(EditText input:new EditText[]{name,email,password,phone,address})form.addView(input,lp(-1,dp(56),0,10));Button submit=button("Enviar cadastro para análise");form.addView(submit,lp(-1,dp(56),8,0));
